from scipy.stats import t as T
L={'bank':np.array([747,726,688,589,582,582.]),'income':np.array([833,727,688,749,643,671.])}
SC={'bank':40,'income':53}
def bp(k):
    c=np.array([-1e9]+cuts+[1e9]); 
    cdf=T.cdf((c[None,:]-L[k][:,None])/SC[k],4)
    return np.diff(cdf,axis=1) # seg x band
BP={k:bp(k) for k in L}
def ev(p): return max(0,float(p@AP))
def val(p,n,memo={}):
    # optimal value with n checks left
    base=ev(p)
    if n==0: return base
    best=base
    for k in L:
        tot=0
        for b in range(6):
            w=p*BP[k][:,b];pb=w.sum()
            if pb>1e-12: tot+=pb*val(w/pb,n-1)
        best=max(best,tot-20)
    return best
def rec(prior,obs,left=8):
    p=np.array(prior,float)
    for k,b in obs: p=p*BP[k][:,b]
    p/=p.sum()
    out={'post':p.round(3).tolist(),'EVnow':ev(p)}
    for k in L:
        for d in (1,2,3):
            if d>left: continue
            def v(p,n):
                return val(p,n)
        tot=0
        for b in range(6):
            w=p*BP[k][:,b];pb=w.sum()
            if pb>1e-12: tot+=pb*val(w/pb,min(left-1,2))
        out[k]=tot-20
    return out
if __name__=='__main__':
    import sys,json
    prior=json.loads(sys.argv[1]);obs=json.loads(sys.argv[2])
    print(rec(prior,obs,8-len(obs)))
